using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Inspects the compiled assemblies (every type they reference, not just project references)
/// so a technical detail used from business code fails the build.
/// </summary>
public class LayerDependencyTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions.Http", "Microsoft.AspNetCore",
    ];

    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_depends_on_no_other_layer_and_no_technical_detail() =>
        AssertClean(typeof(Money).Assembly, [Infrastructure, "PaymentAuthorization.Application"]);

    [Fact]
    public void Application_depends_on_no_infrastructure_and_no_technical_detail() =>
        AssertClean(typeof(AuthorizePayment).Assembly, [Infrastructure]);

    private static void AssertClean(Assembly assembly, string[] forbiddenLayers)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();

        var violations = new SortedSet<string>();
        foreach (var handle in md.AssemblyReferences)
        {
            var name = md.GetString(md.GetAssemblyReference(handle).Name);
            if (forbiddenLayers.Any(l => name == l)) violations.Add($"assembly {name}");
        }
        foreach (var handle in md.TypeReferences)
        {
            var type = md.GetTypeReference(handle);
            var ns = md.GetString(type.Namespace);
            if (TechnicalNamespaces.Any(t => ns == t || ns.StartsWith(t + ".")) ||
                forbiddenLayers.Any(l => ns == l || ns.StartsWith(l + ".")))
                violations.Add($"{ns}.{md.GetString(type.Name)}");
        }

        Assert.True(violations.Count == 0,
            $"{assembly.GetName().Name} must not depend on: {string.Join(", ", violations)}");
    }
}
